function dedupeLines(text, opts){
  opts=opts||{}; var ic=!!opts.ignoreCase; var tw=!!opts.trimWs;
  var lines=String(text||'').split(/\r?\n/);
  var seen={}, out=[];
  for(var i=0;i<lines.length;i++){
    var L=lines[i]; var k=tw?L.trim():L; if(ic) k=k.toLowerCase();
    if(Object.prototype.hasOwnProperty.call(seen,k)) continue;
    seen[k]=1; out.push(L);
  }
  return out.join('\n');
}

var EXPORTS={dedupeLines:dedupeLines};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.DedupeForgePure = EXPORTS; }
